1	// command: the Command's terminal front end (BOLO 153, Chief 10/18 "go": Go + the Charm kit).
2	//
3	//	command up      boot the whole architecture from a shell: VS Code on the repo, then the launch sequence
4	//	                (stations, JUDY, the Console as the viewer), drawn live as the boot screen with the
5	//	                spinning mark and the fetch panel; it holds on "press SPACE to continue"
6	//	command fetch   the mark and the fetch panel, printed once (neofetch for the Command)
7	//
8	// Python stays the engine: launch.py runs the stations and writes boot.jsonl; this program only draws it.
9	// Build: see build.cmd beside this file.
10	package main
11	
12	import (
13		"bufio"
14		"encoding/json"
15		"fmt"
16		"io"
17		"os"
18		"os/exec"
19		"path/filepath"
20		"strings"
21		"time"
22	
23		tea "github.com/charmbracelet/bubbletea"
24		"github.com/charmbracelet/lipgloss"
25		"github.com/charmbracelet/x/ansi"
26	)
27	
28	var root = `C:\Users\U01_LEECHSEED\Desktop\_setsunadev` // set at build time with -ldflags "-X main.root=..."
29	
30	func init() {
31		if r := os.Getenv("COMMAND_ROOT"); r != "" {
32			root = r
33		}
34	}
35	
36	type event struct {
37		T       float64  `json:"t"`
38		State   string   `json:"state"`
39		Station string   `json:"station"`
40		Go      bool     `json:"go"`
41		Note    string   `json:"note"`
42		Waves   []string `json:"waves"`
43		Sub     []string `json:"sub"`
44	}
45	
46	var early = [][2]string{
47		{":: running early hook", "[udev]"}, {":: running hook", "[keymap]"}, {":: mounting", "'/dev/q' on real root"},
48		{":: loading", "the Command · SOP · BOLO · STATE"}, {":: starting", "systemd-launch (BOLO 58)"},
49	}
50	
51	type tickMsg time.Time
52	type launchDone struct{ err error }
53	
54	type model struct {
55		w, h       int
56		start      time.Time
57		startEpoch float64
58		spin       *spinner
59		fetch      [][2]string
60		lines      []string // finished lines: the early hooks, then one per station (plus its sub lines)
61		earlyShown int
62		running    string
63		runSince   time.Time
64		frame      int
65		ok, bad    int
66		ended      bool
67		launchErr  error
68		events     string // path to boot.jsonl
69		offset     int64
70		partial    string
71		logPath    string
72		done       chan launchDone // the launch's exit, sent on once
73	}
74	
75	func stamp(sec float64) string { return sDim.Render(fmt.Sprintf("[%8.3f]", sec)) }
76	
77	func pad(s string, n int) string {
78		if len(s) >= n {
79			return s
80		}
81		return s + strings.Repeat(" ", n-len(s))
82	}
83	
84	func stationLine(e event, sec float64) []string {
85		tag, verdict := sOK.Render("[  OK  ]"), sOK.Render("GO    ")
86		if !e.Go {
87			tag, verdict = sBad.Render("[FAILED]"), sBad.Render("NO-GO ")
88		}
89		note := e.Note
90		if len(e.Waves) > 0 {
91			note = fmt.Sprintf("%d waves open", len(e.Waves))
92		}
93		if len(note) > 52 {
94			note = note[:52]
95		}
96		out := []string{fmt.Sprintf("%s %s %s %s %s %s", stamp(sec), tag, sWhite.Render(pad(e.Station, 10)),
97			sDim.Render(strings.Repeat(".", 30)), verdict, sDim.Render(note))}
98		for _, s := range e.Sub {
99			out = append(out, "           "+sDim.Render("└─ "+trunc(s, 92)))
100		}
101		for _, wv := range e.Waves {
102			st := sOK
103			if strings.Contains(wv, "STALLED") {
104				st = sBad
105			}
106			out = append(out, "           "+sDim.Render("└─ ")+st.Render(trunc(wv, 90)))
107		}
108		return out
109	}
110	
111	func trunc(s string, n int) string {
112		r := []rune(s)
113		if len(r) > n {
114			return string(r[:n])
115		}
116		return s
117	}
118	
119	func tick() tea.Cmd {
120		return tea.Tick(50*time.Millisecond, func(t time.Time) tea.Msg { return tickMsg(t) })
121	}
122	
123	func (m *model) Init() tea.Cmd { return tick() }
124	
125	// readEvents takes the new whole lines of boot.jsonl; events older than this run are the last launch's, skipped
126	func (m *model) readEvents() {
127		f, err := os.Open(m.events)
128		if err != nil {
129			return
130		}
131		defer f.Close()
132		if st, err := f.Stat(); err == nil && st.Size() < m.offset {
133			m.offset, m.partial = 0, "" // the launch truncated the file: start over
134		}
135		f.Seek(m.offset, io.SeekStart)
136		b, _ := io.ReadAll(f)
137		m.offset += int64(len(b))
138		chunk := m.partial + string(b)
139		parts := strings.Split(chunk, "\n")
140		m.partial = parts[len(parts)-1]
141		for _, l := range parts[:len(parts)-1] {
142			var e event
143			if json.Unmarshal([]byte(strings.TrimSpace(l)), &e) != nil || e.T < m.startEpoch-2 {
144				continue
145			}
146			switch e.State {
147			case "start":
148				m.running, m.runSince = e.Station, time.Now()
149			case "done":
150				if e.Go {
151					m.ok++
152				} else {
153					m.bad++
154				}
155				m.lines = append(m.lines, stationLine(e, e.T-m.startEpoch)...)
156				m.running = ""
157			case "end":
158				m.ended = true
159			}
160		}
161	}
162	
163	func (m *model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
164		switch msg := msg.(type) {
165		case tea.WindowSizeMsg:
166			m.w, m.h = msg.Width, msg.Height
167		case tea.KeyMsg:
168			switch msg.String() {
169			case "ctrl+c":
170				return m, tea.Quit
171			case " ", "enter":
172				if m.ended || m.launchErr != nil {
173					return m, tea.Quit
174				}
175			}
176		case launchDone:
177			m.readEvents()
178			if !m.ended {
179				m.launchErr = msg.err
180				if m.launchErr == nil {
181					m.launchErr = fmt.Errorf("the launch ended without its last event")
182				}
183			}
184		case tickMsg:
185			m.frame++
186			if m.earlyShown < len(early) && m.frame%2 == 0 {
187				e := early[m.earlyShown]
188				if e[0] == "" { // the wake-up lines: green, no hook word
189					m.lines = append(m.lines, fmt.Sprintf("%s %s", stamp(0.12*float64(m.earlyShown+1)), sOK.Render(e[1])))
190				} else {
191					m.lines = append(m.lines, fmt.Sprintf("%s %s %s", stamp(0.12*float64(m.earlyShown+1)), sAcc.Render(e[0]), sFg.Render(e[1])))
192				}
193				m.earlyShown++
194				if m.earlyShown == len(early) {
195					m.lines = append(m.lines, "")
196				}
197			} else if m.earlyShown == len(early) {
198				m.readEvents()
199			}
200			return m, tick()
201		}
202		return m, nil
203	}
204	
205	func (m *model) hero(still bool) string {
206		shown := -1
207		if !still {
208			shown = 2 + m.frame/2 // the panel types in, two ticks a line
209		}
210		logo := m.spin.frame(time.Now(), still)
211		return lipgloss.JoinHorizontal(lipgloss.Center, logo, "    ", fetchBlock(m.fetch, shown))
212	}
213	
214	func banner() string {
215		return sAccB.Render("        B  O  L  D  V  E  N  T  U  R  E") + "\n" +
216			sDim.Render("   ── the Command · launch sequence "+strings.Repeat("─", 22))
217	}
218	
219	func (m *model) tail() []string {
220		out := append([]string{}, m.lines...)
221		if m.running != "" {
222			n := int(time.Since(m.runSince).Milliseconds()/80) % 30
223			spin := string("|/-\\"[m.frame%4])
224			out = append(out, fmt.Sprintf("%s %s %s %s", stamp(float64(time.Now().UnixNano())/1e9-m.startEpoch),
225				sAmber.Render("[  "+spin+"   ]"), sWhite.Render(pad(m.running, 10)), sDim.Render(strings.Repeat(".", n+1))))
226		}
227		switch {
228		case m.launchErr != nil:
229			out = append(out, "", sBad.Render("  launch stopped: "+m.launchErr.Error()), sDim.Render("  its output: "+m.logPath), "", sAccB.Render("  press SPACE to continue"))
230		case m.ended:
231			if m.bad > 0 {
232				out = append(out, "", sBad.Render(fmt.Sprintf("  %d NO-GO", m.bad))+sDim.Render(" · ")+sOK.Render(fmt.Sprintf("%d GO", m.ok))+sDim.Render(" · the sit rep carries the details"))
233			} else {
234				out = append(out, "", sOK.Render("  Reached target ")+sAccB.Render("The Command")+sOK.Render(fmt.Sprintf(".  ALL GO (%d)", m.ok)))
235			}
236			if (m.frame/10)%2 == 0 { // the blink
237				out = append(out, "", sAccB.Render("  press SPACE to continue"))
238			} else {
239				out = append(out, "", "")
240			}
241		}
242		return out
243	}
244	
245	// View: the big mark on the left at boot.py's full size (Chief 10/18: "I kinda miss how high fidelity the original
246	// bunny logo was"); the fetch panel, the banner and the station rows stack in the column beside it.
247	func (m *model) View() string {
248		logo := m.spin.frame(time.Now(), false)
249		lw := lipgloss.Width(logo)
250		head := fetchBlock(m.fetch, 2+m.frame/2) + "\n\n" + banner() + "\n"
251		room := max(m.h, lipgloss.Height(logo)) - lipgloss.Height(head) - 1
252		body := m.tail()
253		if room > 0 && len(body) > room {
254			body = body[len(body)-room:]
255		}
256		colW := max(m.w-lw-4, 20)
257		var b strings.Builder
258		b.WriteString(head)
259		for _, l := range body {
260			b.WriteString("\n" + ansi.Truncate(l, colW, ""))
261		}
262		return lipgloss.JoinHorizontal(lipgloss.Top, logo, "    ", b.String())
263	}
264	
265	// pickScale: boot.py's size, always (half the source art each way, 44 rows); the layout makes room beside it
266	func pickScale(art []string, h int) int { return 2 }
267	
268	func termHeight() int {
269		if _, h, err := termSize(); err == nil {
270			return h
271		}
272		return 40
273	}
274	
275	// startLaunch: VS Code on the repo (an open window just gets focus), then the launch sequence, running from here on.
276	// wake calls it before the intro so the stations load under the typing (Chief 10/31: "start loading stuff in the
277	// background as well"); the boot screen then picks up every event since this start.
278	func startLaunch() *model {
279		art := loadArt(filepath.Join(root, "_tools", "brand", "boldventure-ascii.txt"))
280		m := &model{start: time.Now(), events: filepath.Join(root, "_tools", "launch", "boot.jsonl"), fetch: fetchRows()}
281		m.startEpoch = float64(m.start.UnixNano()) / 1e9
282		m.spin = newSpinner(shrink(art, pickScale(art, termHeight())))
283		m.done = make(chan launchDone, 1)
284	
285		exec.Command("cmd", "/c", "code", root).Start()
286		m.logPath = filepath.Join(root, "_tools", "cmdtui", "last_up.log")
287		logf, _ := os.Create(m.logPath)
288		launch := exec.Command("python", "-X", "utf8", filepath.Join(root, "_tools", "launch", "launch.py"))
289		launch.Dir = root
290		launch.Stdout, launch.Stderr = logf, logf
291		if err := launch.Start(); err != nil {
292			m.launchErr = err
293		} else {
294			go func() { err := launch.Wait(); logf.Close(); m.done <- launchDone{err} }()
295		}
296		return m
297	}
298	
299	func up() { upWith(startLaunch()) }
300	
301	func upWith(m *model) {
302		p := tea.NewProgram(m, tea.WithAltScreen())
303		defer musicStop()                // no boot music (Chief 10/31: "remove the bg music"); this only ends the intro's clip if it still plays
304		go func() { p.Send(<-m.done) }() // the launch may already have ended during the intro: the buffered result waits
305		if _, err := p.Run(); err != nil {
306			fmt.Fprintln(os.Stderr, "command up:", err)
307			os.Exit(1)
308		}
309		// leave the board in the scrollback, the way neofetch does
310		fmt.Println(m.hero(true))
311		fmt.Println()
312		for _, l := range m.lines {
313			fmt.Println(l)
314		}
315		if m.ended {
316			fmt.Println(sDim.Render("\n  the poll and the NEXT lines: " + m.logPath))
317		}
318	}
319	
320	// spinModel: command fetch, live (Chief 10/18 "can u make da big bunny head spin"): the mark decodes in and spins
321	// beside the fetch panel, drawn in place; Space or q stops it and leaves the front-facing frame behind.
322	type spinModel struct {
323		s     *spinner
324		rows  [][2]string
325		frame int
326		done  bool
327	}
328	
329	func (m *spinModel) Init() tea.Cmd { return tick() }
330	
331	func (m *spinModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
332		switch msg := msg.(type) {
333		case tea.KeyMsg:
334			switch msg.String() {
335			case " ", "enter", "q", "esc", "ctrl+c":
336				m.done = true
337				return m, tea.Quit
338			}
339		case tickMsg:
340			m.frame++
341			return m, tick()
342		}
343		return m, nil
344	}
345	
346	func (m *spinModel) View() string {
347		if m.done {
348			return lipgloss.JoinHorizontal(lipgloss.Center, m.s.frame(time.Now(), true), "    ", fetchBlock(m.rows, -1)) + "\n"
349		}
350		hint := ""
351		if (m.frame/10)%2 == 0 {
352			hint = sDim.Render("\n\nSPACE · stop")
353		}
354		return lipgloss.JoinHorizontal(lipgloss.Center, m.s.frame(time.Now(), false), "    ", fetchBlock(m.rows, 2+m.frame/2)+hint) + "\n"
355	}
356	
357	func fetchOnce(still bool) {
358		art := loadArt(filepath.Join(root, "_tools", "brand", "boldventure-ascii.txt"))
359		s := newSpinner(shrink(art, pickScale(art, termHeight())))
360		rows := fetchRows()
361		if still {
362			fmt.Println(lipgloss.JoinHorizontal(lipgloss.Center, s.frame(time.Now(), true), "    ", fetchBlock(rows, -1)))
363			return
364		}
365		musicStart()
366		_, err := tea.NewProgram(&spinModel{s: s, rows: rows}).Run()
367		musicStop()
368		if err != nil { // no terminal (a pipe): the still frame
369			fmt.Println(lipgloss.JoinHorizontal(lipgloss.Center, s.frame(time.Now(), true), "    ", fetchBlock(rows, -1)))
370		}
371	}
372	
373	// wakeWords: "Wake Up, Neo." (Chief 10/19) is the go code for up. The shell runs wake.exe (a copy of this program)
374	// and hands it "Up," "Neo." in any case and punctuation; anything that starts with "up" boots.
375	func wakeWords(args []string) bool {
376		w := strings.Fields(strings.Map(func(r rune) rune {
377			if r >= 'a' && r <= 'z' || r == ' ' {
378				return r
379			}
380			return ' '
381		}, strings.ToLower(strings.Join(args, " "))))
382		return len(w) == 0 || w[0] == "up"
383	}
384	
385	func main() {
386		if self := strings.ToLower(filepath.Base(os.Args[0])); strings.TrimSuffix(self, ".exe") == "wake" {
387			if wakeWords(os.Args[1:]) {
388				m := startLaunch() // the stations load while the intro plays
389				if matrixIntro() { // the film's opening on a black screen first (intro.go, Chief 10/31)
390					upWith(m)
391				}
392				return
393			}
394			fmt.Println(sOK.Render("Wake up, Neo...") + sDim.Render("  (say: wake up, neo)"))
395			return
396		}
397		if strings.TrimSuffix(strings.ToLower(filepath.Base(os.Args[0])), ".exe") == "kenshi" { // "Kenshi Watanabi" (Chief 10/19)
398			kenshiCmd(os.Args[1:], kenshiWords(os.Args[1:]))
399			return
400		}
401		if strings.TrimSuffix(strings.ToLower(filepath.Base(os.Args[0])), ".exe") == "fresh" { // "Fresh hour" (Chief 10/30)
402			hourCmd(os.Args[1:])
403			return
404		}
405		cmd := ""
406		if len(os.Args) > 1 {
407			cmd = os.Args[1]
408		}
409		switch cmd {
410		case "kenshi":
411			kenshiCmd(os.Args[2:], kenshiWords(os.Args[2:]))
412		case "goon":
413			goonCmd(os.Args[2:])
414		case "hour":
415			hourCmd(os.Args[2:])
