// command: the Command's terminal front end (BOLO 153, Chief 10/18 "go": Go + the Charm kit).
//
//	command up      boot the whole architecture from a shell: VS Code on the repo, then the launch sequence
//	                (stations, JUDY, the Console as the viewer), drawn live as the boot screen with the
//	                spinning mark and the fetch panel; it holds on "press SPACE to continue"
//	command fetch   the mark and the fetch panel, printed once (neofetch for the Command)
//
// Python stays the engine: launch.py runs the stations and writes boot.jsonl; this program only draws it.
// Build: see build.cmd beside this file.
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/ansi"
)

var root = `C:\Users\U01_LEECHSEED\Desktop\_setsunadev` // set at build time with -ldflags "-X main.root=..."

func init() {
	if r := os.Getenv("COMMAND_ROOT"); r != "" {
		root = r
	}
}

type event struct {
	T       float64  `json:"t"`
	State   string   `json:"state"`
	Station string   `json:"station"`
	Go      bool     `json:"go"`
	Note    string   `json:"note"`
	Waves   []string `json:"waves"`
	Sub     []string `json:"sub"`
}

var early = [][2]string{
	{":: running early hook", "[udev]"}, {":: running hook", "[keymap]"}, {":: mounting", "'/dev/q' on real root"},
	{":: loading", "the Command · SOP · BOLO · STATE"}, {":: starting", "systemd-launch (BOLO 58)"},
}

type tickMsg time.Time
type launchDone struct{ err error }

type model struct {
	w, h       int
	start      time.Time
	startEpoch float64
	spin       *spinner
	fetch      [][2]string
	lines      []string // finished lines: the early hooks, then one per station (plus its sub lines)
	earlyShown int
	running    string
	runSince   time.Time
	frame      int
	ok, bad    int
	ended      bool
	launchErr  error
	events     string // path to boot.jsonl
	offset     int64
	partial    string
	logPath    string
	done       chan launchDone // the launch's exit, sent on once
}

func stamp(sec float64) string { return sDim.Render(fmt.Sprintf("[%8.3f]", sec)) }

func pad(s string, n int) string {
	if len(s) >= n {
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func stationLine(e event, sec float64) []string {
	tag, verdict := sOK.Render("[  OK  ]"), sOK.Render("GO    ")
	if !e.Go {
		tag, verdict = sBad.Render("[FAILED]"), sBad.Render("NO-GO ")
	}
	note := e.Note
	if len(e.Waves) > 0 {
		note = fmt.Sprintf("%d waves open", len(e.Waves))
	}
	if len(note) > 52 {
		note = note[:52]
	}
	out := []string{fmt.Sprintf("%s %s %s %s %s %s", stamp(sec), tag, sWhite.Render(pad(e.Station, 10)),
		sDim.Render(strings.Repeat(".", 30)), verdict, sDim.Render(note))}
	for _, s := range e.Sub {
		out = append(out, "           "+sDim.Render("└─ "+trunc(s, 92)))
	}
	for _, wv := range e.Waves {
		st := sOK
		if strings.Contains(wv, "STALLED") {
			st = sBad
		}
		out = append(out, "           "+sDim.Render("└─ ")+st.Render(trunc(wv, 90)))
	}
	return out
}

func trunc(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
		return string(r[:n])
	}
	return s
}

func tick() tea.Cmd {
	return tea.Tick(50*time.Millisecond, func(t time.Time) tea.Msg { return tickMsg(t) })
}

func (m *model) Init() tea.Cmd { return tick() }

// readEvents takes the new whole lines of boot.jsonl; events older than this run are the last launch's, skipped
func (m *model) readEvents() {
	f, err := os.Open(m.events)
	if err != nil {
		return
	}
	defer f.Close()
	if st, err := f.Stat(); err == nil && st.Size() < m.offset {
		m.offset, m.partial = 0, "" // the launch truncated the file: start over
	}
	f.Seek(m.offset, io.SeekStart)
	b, _ := io.ReadAll(f)
	m.offset += int64(len(b))
	chunk := m.partial + string(b)
	parts := strings.Split(chunk, "\n")
	m.partial = parts[len(parts)-1]
	for _, l := range parts[:len(parts)-1] {
		var e event
		if json.Unmarshal([]byte(strings.TrimSpace(l)), &e) != nil || e.T < m.startEpoch-2 {
			continue
		}
		switch e.State {
		case "start":
			m.running, m.runSince = e.Station, time.Now()
		case "done":
			if e.Go {
				m.ok++
			} else {
				m.bad++
			}
			m.lines = append(m.lines, stationLine(e, e.T-m.startEpoch)...)
			m.running = ""
		case "end":
			m.ended = true
		}
	}
}

func (m *model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.w, m.h = msg.Width, msg.Height
	case tea.KeyMsg:
		switch msg.String() {
		case "ctrl+c":
			return m, tea.Quit
		case " ", "enter":
			if m.ended || m.launchErr != nil {
				return m, tea.Quit
			}
		}
	case launchDone:
		m.readEvents()
		if !m.ended {
			m.launchErr = msg.err
			if m.launchErr == nil {
				m.launchErr = fmt.Errorf("the launch ended without its last event")
			}
		}
	case tickMsg:
		m.frame++
		if m.earlyShown < len(early) && m.frame%2 == 0 {
			e := early[m.earlyShown]
			if e[0] == "" { // the wake-up lines: green, no hook word
				m.lines = append(m.lines, fmt.Sprintf("%s %s", stamp(0.12*float64(m.earlyShown+1)), sOK.Render(e[1])))
			} else {
				m.lines = append(m.lines, fmt.Sprintf("%s %s %s", stamp(0.12*float64(m.earlyShown+1)), sAcc.Render(e[0]), sFg.Render(e[1])))
			}
			m.earlyShown++
			if m.earlyShown == len(early) {
				m.lines = append(m.lines, "")
			}
		} else if m.earlyShown == len(early) {
			m.readEvents()
		}
		return m, tick()
	}
	return m, nil
}

func (m *model) hero(still bool) string {
	shown := -1
	if !still {
		shown = 2 + m.frame/2 // the panel types in, two ticks a line
	}
	logo := m.spin.frame(time.Now(), still)
	return lipgloss.JoinHorizontal(lipgloss.Center, logo, "    ", fetchBlock(m.fetch, shown))
}

func banner() string {
	return sAccB.Render("        B  O  L  D  V  E  N  T  U  R  E") + "\n" +
		sDim.Render("   ── the Command · launch sequence "+strings.Repeat("─", 22))
}

func (m *model) tail() []string {
	out := append([]string{}, m.lines...)
	if m.running != "" {
		n := int(time.Since(m.runSince).Milliseconds()/80) % 30
		spin := string("|/-\\"[m.frame%4])
		out = append(out, fmt.Sprintf("%s %s %s %s", stamp(float64(time.Now().UnixNano())/1e9-m.startEpoch),
			sAmber.Render("[  "+spin+"   ]"), sWhite.Render(pad(m.running, 10)), sDim.Render(strings.Repeat(".", n+1))))
	}
	switch {
	case m.launchErr != nil:
		out = append(out, "", sBad.Render("  launch stopped: "+m.launchErr.Error()), sDim.Render("  its output: "+m.logPath), "", sAccB.Render("  press SPACE to continue"))
	case m.ended:
		if m.bad > 0 {
			out = append(out, "", sBad.Render(fmt.Sprintf("  %d NO-GO", m.bad))+sDim.Render(" · ")+sOK.Render(fmt.Sprintf("%d GO", m.ok))+sDim.Render(" · the sit rep carries the details"))
		} else {
			out = append(out, "", sOK.Render("  Reached target ")+sAccB.Render("The Command")+sOK.Render(fmt.Sprintf(".  ALL GO (%d)", m.ok)))
		}
		if (m.frame/10)%2 == 0 { // the blink
			out = append(out, "", sAccB.Render("  press SPACE to continue"))
		} else {
			out = append(out, "", "")
		}
	}
	return out
}

// View: the big mark on the left at boot.py's full size (Chief 10/18: "I kinda miss how high fidelity the original
// bunny logo was"); the fetch panel, the banner and the station rows stack in the column beside it.
func (m *model) View() string {
	logo := m.spin.frame(time.Now(), false)
	lw := lipgloss.Width(logo)
	head := fetchBlock(m.fetch, 2+m.frame/2) + "\n\n" + banner() + "\n"
	room := max(m.h, lipgloss.Height(logo)) - lipgloss.Height(head) - 1
	body := m.tail()
	if room > 0 && len(body) > room {
		body = body[len(body)-room:]
	}
	colW := max(m.w-lw-4, 20)
	var b strings.Builder
	b.WriteString(head)
	for _, l := range body {
		b.WriteString("\n" + ansi.Truncate(l, colW, ""))
	}
	return lipgloss.JoinHorizontal(lipgloss.Top, logo, "    ", b.String())
}

// pickScale: boot.py's size, always (half the source art each way, 44 rows); the layout makes room beside it
func pickScale(art []string, h int) int { return 2 }

func termHeight() int {
	if _, h, err := termSize(); err == nil {
		return h
	}
	return 40
}

// startLaunch: VS Code on the repo (an open window just gets focus), then the launch sequence, running from here on.
// wake calls it before the intro so the stations load under the typing (Chief 10/31: "start loading stuff in the
// background as well"); the boot screen then picks up every event since this start.
func startLaunch() *model {
	art := loadArt(filepath.Join(root, "_tools", "brand", "boldventure-ascii.txt"))
	m := &model{start: time.Now(), events: filepath.Join(root, "_tools", "launch", "boot.jsonl"), fetch: fetchRows()}
	m.startEpoch = float64(m.start.UnixNano()) / 1e9
	m.spin = newSpinner(shrink(art, pickScale(art, termHeight())))
	m.done = make(chan launchDone, 1)

	exec.Command("cmd", "/c", "code", root).Start()
	m.logPath = filepath.Join(root, "_tools", "cmdtui", "last_up.log")
	logf, _ := os.Create(m.logPath)
	launch := exec.Command("python", "-X", "utf8", filepath.Join(root, "_tools", "launch", "launch.py"))
	launch.Dir = root
	launch.Stdout, launch.Stderr = logf, logf
	if err := launch.Start(); err != nil {
		m.launchErr = err
	} else {
		go func() { err := launch.Wait(); logf.Close(); m.done <- launchDone{err} }()
	}
	return m
}

func up() { upWith(startLaunch()) }

func upWith(m *model) {
	p := tea.NewProgram(m, tea.WithAltScreen())
	defer musicStop()                // no boot music (Chief 10/31: "remove the bg music"); this only ends the intro's clip if it still plays
	go func() { p.Send(<-m.done) }() // the launch may already have ended during the intro: the buffered result waits
	if _, err := p.Run(); err != nil {
		fmt.Fprintln(os.Stderr, "command up:", err)
		os.Exit(1)
	}
	// leave the board in the scrollback, the way neofetch does
	fmt.Println(m.hero(true))
	fmt.Println()
	for _, l := range m.lines {
		fmt.Println(l)
	}
	if m.ended {
		fmt.Println(sDim.Render("\n  the poll and the NEXT lines: " + m.logPath))
	}
}

// spinModel: command fetch, live (Chief 10/18 "can u make da big bunny head spin"): the mark decodes in and spins
// beside the fetch panel, drawn in place; Space or q stops it and leaves the front-facing frame behind.
type spinModel struct {
	s     *spinner
	rows  [][2]string
	frame int
	done  bool
}

func (m *spinModel) Init() tea.Cmd { return tick() }

func (m *spinModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		switch msg.String() {
		case " ", "enter", "q", "esc", "ctrl+c":
			m.done = true
			return m, tea.Quit
		}
	case tickMsg:
		m.frame++
		return m, tick()
	}
	return m, nil
}

func (m *spinModel) View() string {
	if m.done {
		return lipgloss.JoinHorizontal(lipgloss.Center, m.s.frame(time.Now(), true), "    ", fetchBlock(m.rows, -1)) + "\n"
	}
	hint := ""
	if (m.frame/10)%2 == 0 {
		hint = sDim.Render("\n\nSPACE · stop")
	}
	return lipgloss.JoinHorizontal(lipgloss.Center, m.s.frame(time.Now(), false), "    ", fetchBlock(m.rows, 2+m.frame/2)+hint) + "\n"
}

func fetchOnce(still bool) {
	art := loadArt(filepath.Join(root, "_tools", "brand", "boldventure-ascii.txt"))
	s := newSpinner(shrink(art, pickScale(art, termHeight())))
	rows := fetchRows()
	if still {
		fmt.Println(lipgloss.JoinHorizontal(lipgloss.Center, s.frame(time.Now(), true), "    ", fetchBlock(rows, -1)))
		return
	}
	musicStart()
	_, err := tea.NewProgram(&spinModel{s: s, rows: rows}).Run()
	musicStop()
	if err != nil { // no terminal (a pipe): the still frame
		fmt.Println(lipgloss.JoinHorizontal(lipgloss.Center, s.frame(time.Now(), true), "    ", fetchBlock(rows, -1)))
	}
}

// wakeWords: "Wake Up, Neo." (Chief 10/19) is the go code for up. The shell runs wake.exe (a copy of this program)
// and hands it "Up," "Neo." in any case and punctuation; anything that starts with "up" boots.
func wakeWords(args []string) bool {
	w := strings.Fields(strings.Map(func(r rune) rune {
		if r >= 'a' && r <= 'z' || r == ' ' {
			return r
		}
		return ' '
	}, strings.ToLower(strings.Join(args, " "))))
	return len(w) == 0 || w[0] == "up"
}

func main() {
	if self := strings.ToLower(filepath.Base(os.Args[0])); strings.TrimSuffix(self, ".exe") == "wake" {
		if wakeWords(os.Args[1:]) {
			m := startLaunch() // the stations load while the intro plays
			if matrixIntro() { // the film's opening on a black screen first (intro.go, Chief 10/31)
				upWith(m)
			}
			return
		}
		fmt.Println(sOK.Render("Wake up, Neo...") + sDim.Render("  (say: wake up, neo)"))
		return
	}
	if strings.TrimSuffix(strings.ToLower(filepath.Base(os.Args[0])), ".exe") == "kenshi" { // "Kenshi Watanabi" (Chief 10/19)
		kenshiCmd(os.Args[1:], kenshiWords(os.Args[1:]))
		return
	}
	if strings.TrimSuffix(strings.ToLower(filepath.Base(os.Args[0])), ".exe") == "fresh" { // "Fresh hour" (Chief 10/30)
		hourCmd(os.Args[1:])
		return
	}
	cmd := ""
	if len(os.Args) > 1 {
		cmd = os.Args[1]
	}
	switch cmd {
	case "kenshi":
		kenshiCmd(os.Args[2:], kenshiWords(os.Args[2:]))
	case "goon":
		goonCmd(os.Args[2:])
	case "hour":
		hourCmd(os.Args[2:])
	case "slideshow":
		slideshowCmd(os.Args[2:])
	case "up":
		up()
	case "fetch":
		if hasFlag(os.Args[2:], "--json") {
			m := map[string]string{}
			for _, r := range fetchRows() {
				m[r[0]] = r[1]
			}
			b, _ := json.MarshalIndent(m, "", " ")
			fmt.Println(string(b))
			return
		}
		fetchOnce(hasFlag(os.Args[2:], "--still") || hasFlag(os.Args[2:], "--print"))
	case "board":
		boardCmd(os.Args[2:])
	case "md":
		mdCmd(os.Args[2:])
	case "glass":
		glassCmd(os.Args[2:])
	case "pull":
		pullCmd(os.Args[2:])
	case "push":
		pushCmd(os.Args[2:])
	default:
		w := bufio.NewWriter(os.Stdout)
		fmt.Fprintln(w, sAccB.Render("command")+sDim.Render(" · the Command's terminal front end (BOLO 153)"))
		fmt.Fprintln(w, "  "+sAcc.Render("up   ")+"  boot the whole architecture: VS Code, the stations, JUDY, the Console (the go code: wake up, neo)")
		fmt.Fprintln(w, "  "+sAcc.Render("fetch")+"  the mark spinning beside the numbers, neofetch style; Space stops it (--still: one frame)")
		fmt.Fprintln(w, "  "+sAcc.Render("board")+"  the newest sit rep board, one tab per block (--json: the board)")
		fmt.Fprintln(w, "  "+sAcc.Render("md   ")+"  a markdown file in the terminal: sop · bolo · state · projects · any path (--json: its headings)")
		fmt.Fprintln(w, "  "+sAcc.Render("glass")+"  the recent glasses, newest first; Enter opens one in the Console (--json: the list · <id|N> --json: the pick)")
		fmt.Fprintln(w, "  "+sAcc.Render("pull ")+"  the pull waves, live and all (--json: the counts · --boards adds board names)")
		fmt.Fprintln(w, "  "+sAcc.Render("push ")+"  the outgoing check, then Chief types push (--dry-run · --print · --json); held while _tools/release/hold.json says so")
		fmt.Fprintln(w, "  "+sAcc.Render("goon ")+"  the Goon program: a standard hour, hit timer, bust and vape cues, VLC on top, start/end log (--json: the last session · --dry-run)")
		fmt.Fprintln(w, "  "+sAcc.Render("hour  ")+"  a fresh hour of BBC in a new VLC window (go code: fresh hour · --only gay|straight · --minutes N · --dry-run · --json)")
		fmt.Fprintln(w, "  "+sAcc.Render("slideshow")+" a photo slideshow from the DARKROOM as a video in a new VLC window (--minutes N · --seconds N · --dry-run · --json)")
		fmt.Fprintln(w, "  "+sAcc.Render("kenshi")+" start Kenshi with RE_Kenshi and Sentient Sands (the go code: kenshi watanabi · --dry-run · --json)")
		w.Flush()
	}
}

