60		lines      []string // finished lines: the early hooks, then one per station (plus its sub lines)
61		earlyShown int
62		running    string
63		runSince   time.Time
64		frame      int
65		ok, bad    int
66		ended      bool
67		launchErr  error
68		events     string // path to boot.jsonl
69		offset     int64
70		partial    string
71		logPath    string
72		done       chan launchDone // the launch's exit, sent on once
73	}
74	
75	func stamp(sec float64) string { return sDim.Render(fmt.Sprintf("[%8.3f]", sec)) }
76	
77	func pad(s string, n int) string {
78		if len(s) >= n {
79			return s
80		}
81		return s + strings.Repeat(" ", n-len(s))
82	}
83	
84	func stationLine(e event, sec float64) []string {
85		tag, verdict := sOK.Render("[  OK  ]"), sOK.Render("GO    ")
86		if !e.Go {
87			tag, verdict = sBad.Render("[FAILED]"), sBad.Render("NO-GO ")
88		}
89		note := e.Note
90		if len(e.Waves) > 0 {
91			note = fmt.Sprintf("%d waves open", len(e.Waves))
92		}
93		if len(note) > 52 {
94			note = note[:52]
95		}
96		out := []string{fmt.Sprintf("%s %s %s %s %s %s", stamp(sec), tag, sWhite.Render(pad(e.Station, 10)),
97			sDim.Render(strings.Repeat(".", 30)), verdict, sDim.Render(note))}
98		for _, s := range e.Sub {
99			out = append(out, "           "+sDim.Render("└─ "+trunc(s, 92)))
100		}
101		for _, wv := range e.Waves {
102			st := sOK
103			if strings.Contains(wv, "STALLED") {
104				st = sBad
105			}
106			out = append(out, "           "+sDim.Render("└─ ")+st.Render(trunc(wv, 90)))
107		}
108		return out
109	}
110	
111	func trunc(s string, n int) string {
112		r := []rune(s)
113		if len(r) > n {
114			return string(r[:n])
115		}
116		return s
117	}
118	
119	func tick() tea.Cmd {
120		return tea.Tick(50*time.Millisecond, func(t time.Time) tea.Msg { return tickMsg(t) })
121	}
122	
123	func (m *model) Init() tea.Cmd { return tick() }
124	
125	// readEvents takes the new whole lines of boot.jsonl; events older than this run are the last launch's, skipped
126	func (m *model) readEvents() {
127		f, err := os.Open(m.events)
128		if err != nil {
129			return
130		}
131		defer f.Close()
132		if st, err := f.Stat(); err == nil && st.Size() < m.offset {
133			m.offset, m.partial = 0, "" // the launch truncated the file: start over
134		}
135		f.Seek(m.offset, io.SeekStart)
136		b, _ := io.ReadAll(f)
137		m.offset += int64(len(b))
138		chunk := m.partial + string(b)
139		parts := strings.Split(chunk, "\n")
140		m.partial = parts[len(parts)-1]
141		for _, l := range parts[:len(parts)-1] {
142			var e event
143			if json.Unmarshal([]byte(strings.TrimSpace(l)), &e) != nil || e.T < m.startEpoch-2 {
144				continue
145			}
146			switch e.State {
147			case "start":
148				m.running, m.runSince = e.Station, time.Now()
149			case "done":
150				if e.Go {
151					m.ok++
152				} else {
153					m.bad++
154				}
155				m.lines = append(m.lines, stationLine(e, e.T-m.startEpoch)...)
156				m.running = ""
157			case "end":
158				m.ended = true
159			}
160		}
161	}
162	
163	func (m *model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
164		switch msg := msg.(type) {
165		case tea.WindowSizeMsg:
166			m.w, m.h = msg.Width, msg.Height
167		case tea.KeyMsg:
168			switch msg.String() {
169			case "ctrl+c":
170				return m, tea.Quit
171			case " ", "enter":
172				if m.ended || m.launchErr != nil {
173					return m, tea.Quit
174				}
175			}
176		case launchDone:
177			m.readEvents()
178			if !m.ended {
179				m.launchErr = msg.err
180				if m.launchErr == nil {
181					m.launchErr = fmt.Errorf("the launch ended without its last event")
182				}
183			}
184		case tickMsg:
185			m.frame++
186			if m.earlyShown < len(early) && m.frame%2 == 0 {
187				e := early[m.earlyShown]
188				if e[0] == "" { // the wake-up lines: green, no hook word
189					m.lines = append(m.lines, fmt.Sprintf("%s %s", stamp(0.12*float64(m.earlyShown+1)), sOK.Render(e[1])))
190				} else {
191					m.lines = append(m.lines, fmt.Sprintf("%s %s %s", stamp(0.12*float64(m.earlyShown+1)), sAcc.Render(e[0]), sFg.Render(e[1])))
192				}
193				m.earlyShown++
194				if m.earlyShown == len(early) {
195					m.lines = append(m.lines, "")
196				}
197			} else if m.earlyShown == len(early) {
198				m.readEvents()
199			}
200			return m, tick()
201		}
202		return m, nil
203	}
