245	// View: the big mark on the left at boot.py's full size (Chief 10/18: "I kinda miss how high fidelity the original
246	// bunny logo was"); the fetch panel, the banner and the station rows stack in the column beside it.
247	func (m *model) View() string {
248		logo := m.spin.frame(time.Now(), false)
249		lw := lipgloss.Width(logo)
250		head := fetchBlock(m.fetch, 2+m.frame/2) + "\n\n" + banner() + "\n"
251		room := max(m.h, lipgloss.Height(logo)) - lipgloss.Height(head) - 1
252		body := m.tail()
