275	// startLaunch: VS Code on the repo (an open window just gets focus), then the launch sequence, running from here on.
276	// wake calls it before the intro so the stations load under the typing (Chief 10/31: "start loading stuff in the
277	// background as well"); the boot screen then picks up every event since this start.
278	func startLaunch() *model {
279		art := loadArt(filepath.Join(root, "_tools", "brand", "boldventure-ascii.txt"))
280		m := &model{start: time.Now(), events: filepath.Join(root, "_tools", "launch", "boot.jsonl"), fetch: fetchRows()}
281		m.startEpoch = float64(m.start.UnixNano()) / 1e9
282		m.spin = newSpinner(shrink(art, pickScale(art, termHeight())))
283		m.done = make(chan launchDone, 1)
284	
285		exec.Command("cmd", "/c", "code", root).Start()
286		m.logPath = filepath.Join(root, "_tools", "cmdtui", "last_up.log")
287		logf, _ := os.Create(m.logPath)
288		launch := exec.Command("python", "-X", "utf8", filepath.Join(root, "_tools", "launch", "launch.py"))
289		launch.Dir = root
290		launch.Stdout, launch.Stderr = logf, logf
291		if err := launch.Start(); err != nil {
292			m.launchErr = err
293		} else {
294			go func() { err := launch.Wait(); logf.Close(); m.done <- launchDone{err} }()
295		}
296		return m
297	}
