303		defer musicStop()                // no boot music (Chief 10/31: "remove the bg music"); this only ends the intro's clip if it still plays
304		go func() { p.Send(<-m.done) }() // the launch may already have ended during the intro: the buffered result waits
305		if _, err := p.Run(); err != nil {
306			fmt.Fprintln(os.Stderr, "command up:", err)
307			os.Exit(1)
308		}
309		// leave the board in the scrollback, the way neofetch does
310		fmt.Println(m.hero(true))
311		fmt.Println()
312		for _, l := range m.lines {
313			fmt.Println(l)
