385	func main() {
386		if self := strings.ToLower(filepath.Base(os.Args[0])); strings.TrimSuffix(self, ".exe") == "wake" {
387			if wakeWords(os.Args[1:]) {
388				m := startLaunch() // the stations load while the intro plays
389				if matrixIntro() { // the film's opening on a black screen first (intro.go, Chief 10/31)
390					upWith(m)
391				}
392				return
393			}
394			fmt.Println(sOK.Render("Wake up, Neo...") + sDim.Render("  (say: wake up, neo)"))
395			return
396		}
397		if strings.TrimSuffix(strings.ToLower(filepath.Base(os.Args[0])), ".exe") == "kenshi" { // "Kenshi Watanabi" (Chief 10/19)
398			kenshiCmd(os.Args[1:], kenshiWords(os.Args[1:]))
399			return
400		}
401		if strings.TrimSuffix(strings.ToLower(filepath.Base(os.Args[0])), ".exe") == "fresh" { // "Fresh hour" (Chief 10/30)
402			hourCmd(os.Args[1:])
403			return
404		}
405		cmd := ""
406		if len(os.Args) > 1 {
407			cmd = os.Args[1]
408		}
409		switch cmd {
410		case "kenshi":
411			kenshiCmd(os.Args[2:], kenshiWords(os.Args[2:]))
412		case "goon":
413			goonCmd(os.Args[2:])
414		case "hour":
415			hourCmd(os.Args[2:])
416		case "slideshow":
417			slideshowCmd(os.Args[2:])
418		case "up":
419			up()
420		case "fetch":
421			if hasFlag(os.Args[2:], "--json") {
422				m := map[string]string{}
423				for _, r := range fetchRows() {
424					m[r[0]] = r[1]
425				}
426				b, _ := json.MarshalIndent(m, "", " ")
427				fmt.Println(string(b))
428				return
429			}
430			fetchOnce(hasFlag(os.Args[2:], "--still") || hasFlag(os.Args[2:], "--print"))
431		case "board":
432			boardCmd(os.Args[2:])
433		case "md":
434			mdCmd(os.Args[2:])
435		case "glass":
436			glassCmd(os.Args[2:])
437		case "pull":
438			pullCmd(os.Args[2:])
439		case "push":
440			pushCmd(os.Args[2:])
441		default:
442			w := bufio.NewWriter(os.Stdout)
443			fmt.Fprintln(w, sAccB.Render("command")+sDim.Render(" · the Command's terminal front end (BOLO 153)"))
444			fmt.Fprintln(w, "  "+sAcc.Render("up   ")+"  boot the whole architecture: VS Code, the stations, JUDY, the Console (the go code: wake up, neo)")
445			fmt.Fprintln(w, "  "+sAcc.Render("fetch")+"  the mark spinning beside the numbers, neofetch style; Space stops it (--still: one frame)")
446			fmt.Fprintln(w, "  "+sAcc.Render("board")+"  the newest sit rep board, one tab per block (--json: the board)")
447			fmt.Fprintln(w, "  "+sAcc.Render("md   ")+"  a markdown file in the terminal: sop · bolo · state · projects · any path (--json: its headings)")
448			fmt.Fprintln(w, "  "+sAcc.Render("glass")+"  the recent glasses, newest first; Enter opens one in the Console (--json: the list · <id|N> --json: the pick)")
449			fmt.Fprintln(w, "  "+sAcc.Render("pull ")+"  the pull waves, live and all (--json: the counts · --boards adds board names)")
450			fmt.Fprintln(w, "  "+sAcc.Render("push ")+"  the outgoing check, then Chief types push (--dry-run · --print · --json); held while _tools/release/hold.json says so")
451			fmt.Fprintln(w, "  "+sAcc.Render("goon ")+"  the Goon program: a standard hour, hit timer, bust and vape cues, VLC on top, start/end log (--json: the last session · --dry-run)")
452			fmt.Fprintln(w, "  "+sAcc.Render("hour  ")+"  a fresh hour of BBC in a new VLC window (go code: fresh hour · --only gay|straight · --minutes N · --dry-run · --json)")
453			fmt.Fprintln(w, "  "+sAcc.Render("slideshow")+" a photo slideshow from the DARKROOM as a video in a new VLC window (--minutes N · --seconds N · --dry-run · --json)")
